import { transitionStatus } from './transitionStatus.mjs';
import { MISSING_SANCTIONING_RECORD, UNDER_REVIEW } from '../../constants/sanctioningConstants.mjs';

function reviewApplication({ sanctioningRecord, reviewer }) {
    if (!sanctioningRecord)
        return { error: MISSING_SANCTIONING_RECORD };
    const result = transitionStatus({
        sanctioningRecord,
        toStatus: UNDER_REVIEW,
        transitionedBy: reviewer?.reviewerName,
        reason: 'Application under review',
    });
    if (result.error)
        return result;
    if (reviewer)
        sanctioningRecord.reviewer = reviewer;
    sanctioningRecord.reviewedAt = sanctioningRecord.updatedAt;
    return result;
}

export { reviewApplication };
