import { modifyMatchUpNotice, deleteMatchUpsNotice, modifyDrawNotice } from '../notifications/drawNotifications.mjs';
import { matchUpsOf, positionAssignmentsOf } from '../../acquire/structureMembers.mjs';
import { analyzeDraws } from '../../query/tournaments/analyzeDraws.mjs';
import { getMatchUpId } from '../../functions/global/extractors.mjs';
import { getDrawStructures } from '../../acquire/findStructure.mjs';
import { MISSING_TOURNAMENT_RECORD, MISSING_DRAW_DEFINITION } from '../../constants/errorConditionConstants.mjs';
import { MAIN } from '../../constants/drawDefinitionConstants.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';

function pruneDrawDefinition({ matchPlayDrawPositions = true, tournamentRecord, drawDefinition, drawId, }) {
    if (!tournamentRecord)
        return { error: MISSING_TOURNAMENT_RECORD };
    if (!drawDefinition)
        return { error: MISSING_DRAW_DEFINITION };
    let relevantMatchUps = [];
    const { drawsAnalysis } = analyzeDraws({ tournamentRecord });
    if (drawsAnalysis.canBePruned.includes(drawId)) {
        const isMatchPlay = drawsAnalysis.matchPlay.includes(drawId);
        const drawAnalysis = drawsAnalysis.drawAnalysis[drawId];
        const { structures: [mainStructure], } = getDrawStructures({
            stageSequence: 1,
            drawDefinition,
            stage: MAIN,
        });
        if (mainStructure && 'structures' in mainStructure)
            return { ...SUCCESS, matchUps: relevantMatchUps };
        const structureData = drawAnalysis.structuresData.find(({ structureId }) => mainStructure.structureId === structureId);
        const matchUps = (matchUpsOf(mainStructure) ?? []).toSorted((a, b) => a.roundPosition - b.roundPosition);
        relevantMatchUps = matchUps.filter(({ roundNumber }) => !structureData.inactiveRounds.includes(roundNumber));
        const relevantMatchUpIds = relevantMatchUps.map(getMatchUpId);
        const deletedMatchUpIds = matchUps.map(getMatchUpId).filter((matchUpId) => !relevantMatchUpIds.includes(matchUpId));
        if (isMatchPlay) {
            const matchPlayMatchUps = relevantMatchUps
                .filter(({ roundNumber }) => !structureData.inactiveRounds.includes(roundNumber))
                .filter(({ winningSide }) => winningSide);
            const matchPlayMatchUpIds = matchPlayMatchUps.map(getMatchUpId);
            const matchUpIdsToDelete = relevantMatchUpIds.filter((matchUpId) => !matchPlayMatchUpIds.includes(matchUpId));
            deletedMatchUpIds.push(...matchUpIdsToDelete);
            const existingDrawPositionPairings = matchPlayMatchUps
                .flatMap((matchUp) => matchUp.drawPositions ?? [])
                .filter(Boolean);
            const existingDrawPositions = existingDrawPositionPairings.flat();
            const drawPositionsMap = Object.assign({}, ...existingDrawPositions.map((drawPosition, i) => ({
                [drawPosition]: i + 1,
            })));
            matchPlayMatchUps.forEach((matchUp) => {
                const before = JSON.stringify(matchUp.drawPositions);
                if (matchPlayDrawPositions) {
                    matchUp.drawPositions = matchUp.drawPositions.map((drawPosition) => drawPositionsMap[drawPosition]);
                }
                else {
                    delete matchUp.drawPositions;
                }
                if (JSON.stringify(matchUp.drawPositions) !== before) {
                    modifyMatchUpNotice({
                        tournamentId: tournamentRecord?.tournamentId,
                        structureId: mainStructure.structureId,
                        drawDefinition,
                        matchUp,
                    });
                }
            });
            if (matchPlayDrawPositions) {
                const updatedPositionAssignments = positionAssignmentsOf(mainStructure)
                    ?.filter((assignment) => existingDrawPositions.includes(assignment.drawPosition))
                    .map((assignment) => {
                    assignment.drawPosition = drawPositionsMap[assignment.drawPosition];
                    return assignment;
                });
                mainStructure.positionAssignments = updatedPositionAssignments;
            }
            else {
                mainStructure.positionAssignments = [];
            }
            mainStructure.matchUps = matchPlayMatchUps;
            relevantMatchUps = matchPlayMatchUps;
        }
        deleteMatchUpsNotice({
            tournamentId: tournamentRecord?.tournamentId,
            matchUpIds: deletedMatchUpIds,
            drawDefinition,
        });
        modifyDrawNotice({ drawDefinition });
    }
    return { ...SUCCESS, matchUps: relevantMatchUps };
}

export { pruneDrawDefinition };
