import { nowIso } from '../../tools/clock.mjs';
import { UUID } from '../../tools/UUID.mjs';
import { MISSING_OFFICIAL_RECORD } from '../../constants/officiatingConstants.mjs';
import { INVALID_VALUES } from '../../constants/errorConditionConstants.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';

function addCertificationRequirement({ officialRecord, requirementId, certificationFamily, certificationLevel, organisationId, description, requirements, prerequisiteLevels, minimumAssignments, minimumEvaluationScore, validityPeriodMonths, extensions, }) {
    if (!officialRecord)
        return { error: MISSING_OFFICIAL_RECORD };
    if (!certificationFamily)
        return { error: INVALID_VALUES, context: { message: 'Missing certificationFamily' } };
    if (!certificationLevel)
        return { error: INVALID_VALUES, context: { message: 'Missing certificationLevel' } };
    if (!organisationId)
        return { error: INVALID_VALUES, context: { message: 'Missing organisationId' } };
    if (!Array.isArray(requirements) || requirements.length === 0)
        return { error: INVALID_VALUES, context: { message: 'Requirements must be a non-empty array' } };
    const certificationRequirement = {
        requirementId: requirementId || UUID(),
        certificationFamily,
        certificationLevel,
        organisationId,
        description,
        requirements: requirements.map((r) => ({
            ...r,
            itemId: r.itemId || UUID(),
        })),
        prerequisiteLevels,
        minimumAssignments,
        minimumEvaluationScore,
        validityPeriodMonths,
        extensions: extensions ?? [],
    };
    officialRecord.certificationRequirements.push(certificationRequirement);
    officialRecord.updatedAt = nowIso();
    return { ...SUCCESS, certificationRequirement, requirementId: certificationRequirement.requirementId };
}

export { addCertificationRequirement };
