function clearPrimaryVenue({ tournamentRecord, exceptVenueId, }) {
    const cleared = [];
    for (const venue of tournamentRecord.venues ?? []) {
        if (venue.isPrimary && venue.venueId !== exceptVenueId) {
            delete venue.isPrimary;
            cleared.push(venue);
        }
    }
    return cleared;
}

