import { modifyParticipantsNotice } from '../notifications/participantNotifications.mjs';
import { findTournamentParticipant } from '../../acquire/findTournamentParticipant.mjs';
import { requireParams } from '../../helpers/parameters/requireParams.mjs';
import { MISSING_VALUE, PARTICIPANT_NOT_FOUND } from '../../constants/errorConditionConstants.mjs';
import { TOURNAMENT_RECORD, PARTICIPANT_ID } from '../../constants/attributeConstants.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';

function modifyParticipantName({ tournamentRecord, participantName, participantId }) {
    const paramsCheck = requireParams({ tournamentRecord, participantId }, [TOURNAMENT_RECORD, PARTICIPANT_ID]);
    if (paramsCheck.error)
        return paramsCheck;
    if (!participantName)
        return { error: MISSING_VALUE, info: 'Missing participantName' };
    const { participant } = findTournamentParticipant({
        tournamentRecord,
        participantId,
    });
    if (!participant)
        return { error: PARTICIPANT_NOT_FOUND };
    participant.participantName = participantName;
    modifyParticipantsNotice({
        tournamentId: tournamentRecord.tournamentId,
        participants: [participant],
    });
    return { ...SUCCESS };
}

export { modifyParticipantName };
