import { modifyParticipantsNotice } from '../notifications/participantNotifications.mjs';
import { findTournamentParticipant } from '../../acquire/findTournamentParticipant.mjs';
import { requireParams } from '../../helpers/parameters/requireParams.mjs';
import { nowIso } from '../../tools/clock.mjs';
import { MISSING_VALUE, PARTICIPANT_NOT_FOUND } from '../../constants/errorConditionConstants.mjs';
import { TOURNAMENT_RECORD, PARTICIPANT_ID } from '../../constants/attributeConstants.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';

function addParticipantOtherId({ tournamentRecord, organisationId, participantId, otherParticipantId, uniqueOrganisationName, }) {
    const paramsCheck = requireParams({ tournamentRecord, participantId }, [TOURNAMENT_RECORD, PARTICIPANT_ID]);
    if (paramsCheck.error)
        return paramsCheck;
    if (!organisationId)
        return { error: MISSING_VALUE, info: 'Missing organisationId' };
    if (!otherParticipantId)
        return { error: MISSING_VALUE, info: 'Missing otherParticipantId' };
    const { participant } = findTournamentParticipant({ tournamentRecord, participantId });
    if (!participant)
        return { error: PARTICIPANT_NOT_FOUND };
    participant.participantOtherIds ??= [];
    const existing = participant.participantOtherIds.find((entry) => entry?.organisationId === organisationId);
    if (existing) {
        if (existing.participantId === otherParticipantId)
            return { ...SUCCESS };
        existing.participantId = otherParticipantId;
        if (uniqueOrganisationName)
            existing.uniqueOrganisationName = uniqueOrganisationName;
        existing.updatedAt = nowIso();
    }
    else {
        participant.participantOtherIds.push({
            organisationId,
            participantId: otherParticipantId,
            ...(uniqueOrganisationName ? { uniqueOrganisationName } : {}),
            createdAt: nowIso(),
        });
    }
    modifyParticipantsNotice({
        tournamentId: tournamentRecord.tournamentId,
        participants: [participant],
    });
    return { ...SUCCESS };
}

export { addParticipantOtherId };
