import { getSourceStructureIdsAndRelevantLinks } from '../../../query/structure/getSourceStructureIdsAndRelevantLinks.mjs';
import { qualifierDrawPositionAssignment } from '../../matchUps/drawPositions/positionQualifier.mjs';
import { checkRequiredParameters } from '../../../helpers/parameters/checkRequiredParameters.mjs';
import { getAllStructureMatchUps } from '../../../query/matchUps/getAllStructureMatchUps.mjs';
import { isCompletedStructure } from '../../../query/drawDefinition/structureActions.mjs';
import { getAppliedPolicies } from '../../../query/extensions/getAppliedPolicies.mjs';
import { firstClassOrExtension } from '../../../acquire/firstClassOrExtension.mjs';
import { decorateResult } from '../../../functions/global/decorateResult.mjs';
import { mapNumbersToIndexes } from '../../../tools/mapNumbersToIndexes.mjs';
import { definedAttributes } from '../../../tools/definedAttributes.mjs';
import { generateRange } from '../../../tools/arrays.mjs';
import { TOURNAMENT_RECORD, EVENT, DRAW_DEFINITION } from '../../../constants/attributeConstants.mjs';
import { MAIN, QUALIFYING, WINNER, POSITION } from '../../../constants/drawDefinitionConstants.mjs';
import { POLICY_TYPE_POSITION_ACTIONS } from '../../../constants/policyConstants.mjs';
import { BYE } from '../../../constants/matchUpStatusValues.mjs';
import { TALLY } from '../../../constants/extensionConstants.mjs';
import { SUCCESS } from '../../../constants/resultConstants.mjs';
